package com.proyecto.backus.service;
import com.proyecto.backus.model.*;
import com.proyecto.backus.repository.*;
import org.junit.jupiter.api.Test;
import java.lang.reflect.Proxy;
import java.math.BigDecimal;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
class PedidosAdminServiceTest {
 @SuppressWarnings("unchecked") <T>T repo(Class<T> t,java.util.function.BiFunction<String,Object[],Object> fn){return (T)Proxy.newProxyInstance(t.getClassLoader(),new Class<?>[]{t},(p,m,a)->fn.apply(m.getName(),a));}
 Inventario inventario(){var p=new Producto();p.setNombre("Cristal");var pr=new Presentacion();pr.setProducto(p);pr.setDescripcion("Paquete de 6");pr.setPrecio(new BigDecimal("24.00"));var i=new Inventario();i.setPresentacion(pr);i.setCantidad(20);return i;}
 @Test void detalleUsaPrecioConfirmadoNoPrecioActual()throws Exception{var p=new Pedido();var id=Pedido.class.getDeclaredField("id");id.setAccessible(true);id.set(p,12L);p.setTotal(new BigDecimal("48.00"));p.setZona("Arequipa");var d=new DetallePedido();d.setInventario(inventario());d.getInventario().getPresentacion().setPrecio(new BigDecimal("50.00"));d.setCantidad(2);d.setPrecioUnitario(new BigDecimal("24.00"));var detalle=PedidosAdminService.transformar(p,List.of(d));assertEquals("DEMO-0012",detalle.numero());assertEquals(new BigDecimal("48.00"),detalle.lineas().getFirst().subtotal());assertEquals("Sin bodega asociada",detalle.bodega());assertEquals(2,detalle.bultos());}
 @Test void reconoceNumeroConPrefijo(){assertEquals(12L,PedidosAdminService.numero("DEMO-0012"));assertEquals(12L,PedidosAdminService.numero("12"));assertNull(PedidosAdminService.numero("Bodega Ana"));}
 @Test void rechazaFechasInvertidas(){var s=new PedidosAdminService(null,null);assertThrows(IllegalArgumentException.class,()->s.listar("",java.time.LocalDate.of(2026,10,29),java.time.LocalDate.of(2026,10,28),0));}
 @Test void confirmacionGuardaDatosDelUsuarioAutenticado(){var i=inventario();var u=new Usuario();u.setNombre("Ana");u.setBodega("Bodega Ana");u.setCorreo("ana@demo.pe");u.setTelefono("999111222");u.setDireccion("Calle 10");u.setRuc("20123456789");u.setDistrito("Cercado");u.setProvincia("Arequipa");u.setDepartamento("Arequipa");var inv=repo(InventarioRepository.class,(m,a)->Optional.of(i));var pedidos=repo(PedidoRepository.class,(m,a)->a[0]);var lineas=repo(DetallePedidoRepository.class,(m,a)->a[0]);var usuarios=repo(UsuarioRepository.class,(m,a)->{assertEquals("ana@demo.pe",a[0]);return Optional.of(u);});var servicio=new PedidoService(inv,pedidos,lineas,usuarios);var p=servicio.confirmar(Map.of(1L,2),"Arequipa",new BigDecimal("48.00"),"ana@demo.pe");u.setBodega("Nombre cambiado");assertEquals("Bodega Ana",p.getBodegaNombre());assertEquals("Ana",p.getResponsable());assertEquals("999111222",p.getTelefonoContacto());assertEquals(18,i.getCantidad());}
 @Test void visitanteNoInventaBodega(){var i=inventario();var servicio=new PedidoService(repo(InventarioRepository.class,(m,a)->Optional.of(i)),repo(PedidoRepository.class,(m,a)->a[0]),repo(DetallePedidoRepository.class,(m,a)->a[0]),repo(UsuarioRepository.class,(m,a)->{fail("No debe buscar usuario para un visitante");return null;}));assertThrows(IllegalArgumentException.class,()->servicio.confirmar(Map.of(1L,1),"Arequipa",new BigDecimal("24.00"),null));assertEquals(20,i.getCantidad());}
 @Test void perfilIncompletoNoDescuentaStock(){var i=inventario();var u=new Usuario();var servicio=new PedidoService(repo(InventarioRepository.class,(m,a)->{fail("No debe bloquear inventario incompleto");return null;}),null,null,repo(UsuarioRepository.class,(m,a)->Optional.of(u)));var error=assertThrows(IllegalArgumentException.class,()->servicio.confirmar(Map.of(1L,1),"Arequipa",new BigDecimal("24.00"),"ana@demo.pe"));assertTrue(error.getMessage().contains("RUC"));assertTrue(error.getMessage().contains("Dirección"));assertEquals(20,i.getCantidad());}
 @Test void identificaCamposYFormatosPendientes(){var u=new Usuario();assertEquals(6,PedidoService.camposPendientes(u).size());u.setTelefono("abc123456789");u.setRuc("123");assertEquals(6,PedidoService.camposPendientes(u).size());u.setTelefono("999111222");u.setRuc("20123456789");assertEquals(4,PedidoService.camposPendientes(u).size());}
}
